class UeUnsupported(Exception):
    pass


class CapabilitiesMismatched(Exception):
    pass


class VerifyAttachTimeout(Exception):
    pass


class VerifyThroughputError(Exception):
    def __init__(
        self,
        msg,  # type: str
        throughput=None,  # type: list
    ):
        self.throughput = throughput
        super(VerifyThroughputError, self).__init__(msg)


class NoSumStatError(Exception):
    pass


class TrafficDirectionNotSupported(Exception):
    pass


class IperfThroughputCheckerNotExist(Exception):
    pass


class IperfVersionNotSupported(Exception):
    pass


class SyslogNotCollected(Exception):
    pass


class NoKeyWordFoundInIperfLog(Exception):
    pass


class CheckUeIpFailedAfterAttach(Exception):
    pass
